/// <summary>
/// This is an extension class for HMIMItemMaterialList form.
/// </summary>
[ExtensionOf(formStr(HMIMItemMaterialList))]
final class METHMIMItemMaterialForm_Extension
{
    public SysLookupMultiSelectCtrl multiSelectCtrl;
    
}

Method.Source:
    /// <summary>
    /// Initializes the multi select query.
    /// </summary>
    public void init()
    {
        FormStringControl hazard;

        next init();
        hazard = this.design().controlName(formControlStr(HMIMItemMaterialList, METHMIMItemMaterial_SubsideryHazard));
        Query query = new Query();
        QueryBuildDataSource queryBuildDataSource;
        queryBuildDataSource = query.addDataSource(tableNum(HMIMDivision));
        queryBuildDataSource.fields().addField(fieldNum(HMIMDivision, DivisionCode));
        queryBuildDataSource.fields().addField(fieldNum(HMIMDivision, Description));
        multiSelectCtrl = SysLookupMultiSelectCtrl::constructWithQuery(this, hazard, query);

        this.parmMultiSelectCtrl(multiSelectCtrl);
    }

    /// <summary>
    /// Re-initializing the values in the dropdown selection based on the SubSideryHazard stored value.
    /// </summary>
    public void run()
    {
        next run();

        METHMIMItemMaterial metHMIMItemMaterial = this.dataSource(FormDataSourceStr(HMIMItemMaterialList, METHMIMItemMaterial)).cursor() as METHMIMItemMaterial;

        if (metHMIMItemMaterial.SubsideryHazard)
        {
            multiSelectCtrl.set(this.getSelectedNotes(metHMIMItemMaterial.SubsideryHazard));
            this.parmMultiSelectCtrl(multiSelectCtrl);
        }
    }

    /// <summary>
    /// This is a parameter method for multi select values.
    /// </summary>
    /// <param name = "_multiSelectCtrl">_multiSelectCtrl.</param>
    /// <returns>Return the  object memory for class SysLookupMultiSelectCtrl.</returns>
    public SysLookupMultiSelectCtrl parmMultiSelectCtrl(SysLookupMultiSelectCtrl _multiSelectCtrl = multiSelectCtrl)
    {
        multiSelectCtrl = _multiSelectCtrl;

        return multiSelectCtrl;
    }

    /// <summary>
    /// Retrieve the values from input and convert it into a container of values.
    /// </summary>
    /// <param name = "_noteStr">_noteStr</param>
    /// <returns>Container with values.</returns>
    private container getSelectedNotes(METSubsideryHazard _noteStr)
    {
        HMIMDivision hmimDivision;
        container tmpValues, conIds, conName;
        int idx;

        if (_noteStr)
        {
            tmpValues = str2con(_noteStr, METConstants::AddressSeperator);
        }

        for (idx = 1; idx <= conLen(tmpValues); idx++)
        {
            hmimDivision = HMIMDivision::find(conPeek(tmpValues, idx));

            if (hmimDivision.RecId)
            {
                conIds += hmimDivision.RecId;
                conName += hmimDivision.DivisionCode;
            }
        }

        return [conIds, conName, conIds];
    }
